import { FormEvent, useEffect, useRef, useState } from "react";
import type { ReactNode } from "react";
import { ArrowLeft, BarChart3, BookOpen, Check, ChevronRight, CircleAlert, ClipboardList, Edit3, FileText, Library, Plus, RefreshCw, Search, Settings2, Shield, UserRound, Users, X } from "lucide-react";
import { supabase } from "@/lib/supabase";

type Row = Record<string, any>;
type Tab = "painel" | "livros" | "autores" | "editoras" | "categorias" | "exemplares" | "localizacao" | "leitores" | "emprestimos" | "devolucoes" | "reservas" | "bloqueios" | "inventario" | "relatorios" | "configuracoes" | "auditoria" | "ajuda";
type Props = { user: any; onBack: () => void; onLogout: () => void };
const tabs: { key: Tab; label: string; icon: any }[] = [
  { key: "painel", label: "Painel", icon: BarChart3 }, { key: "livros", label: "Livros", icon: BookOpen }, { key: "autores", label: "Autores", icon: UserRound }, { key: "editoras", label: "Editoras", icon: Library }, { key: "categorias", label: "Categorias", icon: ClipboardList }, { key: "exemplares", label: "Exemplares", icon: FileText }, { key: "localizacao", label: "Estantes e prateleiras", icon: Library }, { key: "leitores", label: "Leitores", icon: Users }, { key: "emprestimos", label: "Empréstimos", icon: ChevronRight }, { key: "devolucoes", label: "Devoluções", icon: Check }, { key: "reservas", label: "Reservas", icon: ClipboardList }, { key: "bloqueios", label: "Bloqueios", icon: Shield }, { key: "inventario", label: "Inventário", icon: FileText }, { key: "relatorios", label: "Relatórios", icon: BarChart3 }, { key: "configuracoes", label: "Configurações", icon: Settings2 }, { key: "auditoria", label: "Auditoria", icon: Shield }, { key: "ajuda", label: "Ajuda", icon: CircleAlert },
];
const workspaces: { key: string; label: string; description: string; icon: any; items: Tab[] }[] = [
  { key: "overview", label: "Visão geral", description: "Indicadores e pendências do dia", icon: BarChart3, items: ["painel"] },
  { key: "service", label: "Atendimento", description: "Leitores e circulação", icon: Users, items: ["leitores", "emprestimos", "devolucoes", "reservas", "bloqueios"] },
  { key: "collection", label: "Acervo", description: "Catálogo e localização", icon: BookOpen, items: ["livros", "exemplares", "autores", "editoras", "categorias", "localizacao"] },
  { key: "inventory", label: "Inventário", description: "Contagem e divergências", icon: ClipboardList, items: ["inventario"] },
  { key: "reports", label: "Relatórios", description: "Indicadores e exportações", icon: BarChart3, items: ["relatorios"] },
  { key: "admin", label: "Administração", description: "Regras, auditoria e ajuda", icon: Settings2, items: ["configuracoes", "auditoria", "ajuda"] },
];
const text = (e: any) => { const message = String(e?.message || ""); return /tenant|saas|backend|legad|supabase|rpc|trigger|rls|sql|schema|permission denied|violates|relation|function .* does not exist/i.test(message) ? "Não foi possível concluir a operação. Verifique os dados informados ou procure a equipe responsável." : message || "Não foi possível concluir a operação."; };
const statusLabel = (value: any) => { const labels: Record<string, string> = { ATIVO: "Ativo", INATIVO: "Inativo", SUSPENSO: "Suspenso", ABERTO: "Em aberto", PARCIAL: "Parcial", ATRASADO: "Atrasado", DEVOLVIDO: "Devolvido", DISPONIVEL: "Disponível", EM_EXECUCAO: "Em andamento", CONCLUIDO: "Concluído", CANCELADO: "Cancelado", PENDENTE: "Pendente", LIDO: "Conferido", RESOLVIDO: "Resolvido" }; return labels[String(value)] || String(value || "—").replaceAll("_", " "); };
const nameOf = (u: any) => u?.user_metadata?.full_name || u?.user_metadata?.name || u?.email?.split("@")[0] || "Usuário";
const date = (v: any) => v ? new Date(String(v).includes("T") ? v : `${v}T12:00:00`).toLocaleDateString("pt-BR") : "—";
const dayKey = (v: any) => v ? new Date(v).toLocaleDateString("en-CA") : "";
const time = (v: any) => v ? new Date(v).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" }) : "—";

export function LibraryManagementModule({ user, onBack, onLogout }: Props) {
  const [tab, setTab] = useState<Tab>("painel"); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [notice, setNotice] = useState<{ kind: "ok" | "error"; text: string } | null>(null); const [search, setSearch] = useState("");
  const [books, setBooks] = useState<Row[]>([]); const [readers, setReaders] = useState<Row[]>([]); const [copies, setCopies] = useState<Row[]>([]); const [loans, setLoans] = useState<Row[]>([]); const [loanItems, setLoanItems] = useState<Row[]>([]); const [authors, setAuthors] = useState<Row[]>([]); const [publishers, setPublishers] = useState<Row[]>([]); const [categories, setCategories] = useState<Row[]>([]); const [shelves, setShelves] = useState<Row[]>([]); const [racks, setRacks] = useState<Row[]>([]); const [reservations, setReservations] = useState<Row[]>([]); const [inventories, setInventories] = useState<Row[]>([]); const [inventoryItems, setInventoryItems] = useState<Row[]>([]); const [audit, setAudit] = useState<Row[]>([]); const [notifications, setNotifications] = useState<Row[]>([]); const [config, setConfig] = useState<Row>({});
  const [editing, setEditing] = useState<Row | null>(null); const [form, setForm] = useState<string | null>(null); const [initialReaderId, setInitialReaderId] = useState<number | null>(null); const [confirm, setConfirm] = useState<{ title: string; message: string; action: () => Promise<void> } | null>(null); const [bookAuthors, setBookAuthors] = useState<Row[]>([]); const [bookCategories, setBookCategories] = useState<Row[]>([]); const [documents, setDocuments] = useState<Row[]>([]); const [blocks, setBlocks] = useState<Row[]>([]); const [profile, setProfile] = useState<Row | null>(null); const [authorized, setAuthorized] = useState<boolean | null>(null); const setError = (e: any) => setNotice({ kind: "error", text: text(e) });
  const load = async () => { setLoading(true); const q = async (table: string) => supabase.from(table).select("*").limit(1000); const [b, r, c, l, li, a, p, g, es, pr, rs, bl, inv, invItems, au, nt, docs, la, lc, cf] = await Promise.all([q("bib_livros"), q("bib_leitores"), q("bib_exemplares"), q("bib_emprestimos"), q("bib_emprestimo_itens"), q("bib_autores"), q("bib_editoras"), q("bib_categorias"), q("bib_estantes"), q("bib_prateleiras"), q("bib_reservas"), q("bib_bloqueios"), q("bib_inventarios"), q("bib_inventario_itens"), q("bib_auditoria"), q("bib_notificacoes"), q("bib_documentos"), q("bib_livro_autores"), q("bib_livro_categorias"), q("bib_configuracoes")]); const me = await supabase.from("usuarios").select("id,uuid,perfil,ativo,orgao_id").eq("uuid", user?.id).maybeSingle(); const access = await supabase.rpc("bib_pode_acessar"); setAuthorized(access.data === true); setBooks(b.data || []); setReaders(r.data || []); setCopies(c.data || []); setLoans(l.data || []); setLoanItems(li.data || []); setAuthors(a.data || []); setPublishers(p.data || []); setCategories(g.data || []); setRacks(es.data || []); setShelves(pr.data || []); setReservations(rs.data || []); setBlocks(bl.data || []); setInventories(inv.data || []); setInventoryItems(invItems.data || []); setAudit(au.data || []); setNotifications(nt.data || []); setDocuments(docs.data || []); setBookAuthors(la.data || []); setBookCategories(lc.data || []); setConfig(cf.data?.[0] || {}); setProfile(me.data || null); const first = [b, r, c, l, li, a, p, g, es, pr, rs, bl, inv, invItems, au, nt, docs, la, lc, cf, access].find((x) => x.error); if (first?.error) setError(first.error); setLoading(false); };
  useEffect(() => { void load(); }, []); useEffect(() => { setSearch(""); setEditing(null); setForm(null); setInitialReaderId(null); setNotice(null); setConfirm(null); }, [tab]); useEffect(() => { const channel = supabase.channel(`biblioteca-circulacao-${user?.id || "session"}`).on("postgres_changes", { event: "*", schema: "public", table: "bib_emprestimos" }, () => void load()).on("postgres_changes", { event: "*", schema: "public", table: "bib_emprestimo_itens" }, () => void load()).on("postgres_changes", { event: "*", schema: "public", table: "bib_exemplares" }, () => void load()).subscribe(); return () => { void supabase.removeChannel(channel); }; }, [user?.id]);
  const canManage = authorized === true; const activeBooks = books.filter((x) => x.ativo !== false); const activeReaders = readers.filter((x) => x.status === "ATIVO"); const available = copies.filter((x) => x.situacao === "DISPONIVEL" && x.ativo !== false); const overdue = loans.filter((x) => ["ABERTO", "PARCIAL", "ATRASADO"].includes(x.status) && x.prazo_devolucao && new Date(x.prazo_devolucao) < new Date()); const bookTitle = (id: any) => books.find((x) => x.id === id)?.titulo || `Livro #${id}`; const readerName = (id: any) => readers.find((x) => x.id === id)?.nome || `Leitor #${id}`;
  const save = async (table: string, payload: Row, id?: any) => { setBusy(true); const r = id ? await supabase.from(table).update(payload).eq("id", id) : await supabase.from(table).insert(payload); setBusy(false); if (r.error) setError(r.error); else { setNotice({ kind: "ok", text: id ? "Cadastro atualizado." : "Cadastro criado." }); setForm(null); setEditing(null); await load(); } };
  const toggle = (table: string, row: Row, field = "ativo") => { const next = field === "status" ? (row.status === "ATIVO" ? "INATIVO" : "ATIVO") : (row[field] === false); setConfirm({ title: next === "INATIVO" || next === false ? "Confirmar inativação" : "Confirmar alteração", message: "Deseja realmente alterar o status deste cadastro?", action: async () => { setBusy(true); const payload = field === "status" ? { status: next } : { [field]: next }; const r = await supabase.from(table).update(payload).eq("id", row.id); setBusy(false); if (r.error) setError(r.error); else { setNotice({ kind: "ok", text: "Cadastro alterado com sucesso." }); await load(); } } }); };
  const submitBook = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const d = new FormData(e.currentTarget); const payload = { titulo: String(d.get("titulo") || "").trim(), subtitulo: String(d.get("subtitulo") || "").trim() || null, isbn: String(d.get("isbn") || "").trim() || null, editora_id: d.get("editora_id") ? Number(d.get("editora_id")) : null, ano_publicacao: Number(d.get("ano") || 0) || null, edicao: String(d.get("edicao") || "").trim() || null, idioma: String(d.get("idioma") || "Português"), numero_paginas: Number(d.get("paginas") || 0) || null, sinopse: String(d.get("sinopse") || "").trim() || null, ativo: editing?.ativo !== false }; setBusy(true); const result = editing ? await supabase.from("bib_livros").update(payload).eq("id", editing.id).select("id").single() : await supabase.from("bib_livros").insert(payload).select("id").single(); if (result.error) { setBusy(false); return setError(result.error); } const livroId = result.data.id; const authorIds = d.getAll("autor_id").map(Number).filter(Boolean); const categoryIds = d.getAll("categoria_id").map(Number).filter(Boolean); const oldA = await supabase.from("bib_livro_autores").delete().eq("livro_id", livroId); const oldC = await supabase.from("bib_livro_categorias").delete().eq("livro_id", livroId); if (oldA.error || oldC.error) { setBusy(false); return setError(oldA.error || oldC.error); } if (authorIds.length) { const r = await supabase.from("bib_livro_autores").insert(authorIds.map((autor_id, ordem) => ({ livro_id: livroId, autor_id, ordem: ordem + 1 }))); if (r.error) { setBusy(false); return setError(r.error); } } if (categoryIds.length) { const r = await supabase.from("bib_livro_categorias").insert(categoryIds.map((categoria_id) => ({ livro_id: livroId, categoria_id }))); if (r.error) { setBusy(false); return setError(r.error); } } setBusy(false); setNotice({ kind: "ok", text: editing ? "Livro e associações atualizados." : "Livro e associações cadastrados." }); setForm(null); setEditing(null); await load(); };
  const submitReader = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const d = new FormData(e.currentTarget); void save("bib_leitores", { nome: String(d.get("nome")).trim(), cpf: String(d.get("cpf") || "").trim() || null, codigo_carteirinha: String(d.get("carteirinha") || "").trim() || null, email: String(d.get("email") || "").trim() || null, telefone: String(d.get("telefone") || "").trim() || null, tipo_leitor: String(d.get("tipo") || "COMUNIDADE"), status: String(d.get("status") || "ATIVO") }, editing?.id); };
  const openNew = () => { setEditing(null); setForm(tab); }; const initials = nameOf(user).split(" ").slice(0, 2).map((x: string) => x[0]).join("").toUpperCase();
  return <div className="dashboard-shell library-shell"><header className="app-header"><button className="header-back-button" type="button" onClick={onBack}><ArrowLeft size={16} /> Voltar às secretarias</button><div className="user-menu"><div className="user-copy"><strong>{nameOf(user)}</strong><span>{user.email}</span></div><div className="user-avatar user-avatar--initials">{initials}</div><button className="user-menu-button" type="button" onClick={onLogout}>×</button></div></header><main className="library-main"><div className="library-kicker"><span><Library size={15} /> Secretaria de Cultura e Turismo</span><span className="library-secure"><i /> Ambiente protegido</span></div><div className="library-heading"><div><p className="eyebrow">Gestão de Biblioteca Municipal</p><h1>Acervo, circulação e atendimento em um só lugar</h1><p>Controle completo do acervo, atendimento aos leitores, circulação e inventário em um só lugar.</p></div><button className="library-refresh" type="button" onClick={() => void load()}><RefreshCw size={15} /> Atualizar</button></div><div className="library-metrics"><Metric icon={BookOpen} value={activeBooks.length} label="Livros ativos" tone="purple" /><Metric icon={Users} value={activeReaders.length} label="Leitores ativos" tone="blue" /><Metric icon={Check} value={available.length} label="Exemplares disponíveis" tone="green" /><Metric icon={CircleAlert} value={overdue.length} label="Em atraso" tone="orange" /></div><WorkspaceNavigation tab={tab} setTab={setTab} />{notice && <FeedbackModal notice={notice} onClose={() => setNotice(null)} />} {confirm && <ConfirmModal confirm={confirm} busy={busy} onCancel={() => setConfirm(null)} onConfirm={async () => { const action = confirm.action; setConfirm(null); await action(); }} />}{loading ? <div className="library-empty"><RefreshCw className="spin" size={22} /> Carregando dados da Biblioteca...</div> : !authorized ? <LibraryAccessDenied onBack={onBack} /> : <Content user={user} tab={tab} setTab={setTab} search={search} setSearch={setSearch} busy={busy} openNew={openNew} form={form} editing={editing} setEditing={setEditing} setForm={setForm} books={books} readers={readers} copies={copies} loans={loans} loanItems={loanItems} authors={authors} publishers={publishers} categories={categories} racks={racks} shelves={shelves} reservations={reservations} inventories={inventories} inventoryItems={inventoryItems} audit={audit} notifications={notifications} documents={documents} blocks={blocks} bookAuthors={bookAuthors} bookCategories={bookCategories} profile={profile} canManage={canManage} config={config} activeBooks={activeBooks} setConfirm={setConfirm} initialReaderId={initialReaderId} setInitialReaderId={setInitialReaderId} activeReaders={activeReaders} available={available} overdue={overdue} bookTitle={bookTitle} readerName={readerName} save={save} toggle={toggle} submitBook={submitBook} submitReader={submitReader} setNotice={setNotice} load={load} />}<footer className="library-footer"><span><Settings2 size={14} /> Operações registradas com segurança e histórico completo</span><button type="button" onClick={onLogout}>Sair da conta</button></footer></main></div>;
}
function LibraryAccessDenied(p: { onBack: () => void }) { return <section className="library-panel library-access-denied"><Shield size={28} /><span className="section-kicker">Acesso institucional</span><h2>Acesso restrito à Biblioteca Municipal</h2><p>Este módulo está disponível apenas para usuários autorizados da Secretaria de Cultura e Turismo.</p><button type="button" onClick={p.onBack}>Voltar às secretarias</button></section>; }

function Content(p: any) { const { tab } = p; if (tab === "painel") return <Dashboard {...p} />; if (tab === "ajuda") return <Help />; if (tab === "configuracoes") return <ConfigPanel {...p} />; if (tab === "auditoria") return <AuditPanel {...p} />; if (tab === "inventario") return <InventoryPanel {...p} />; if (tab === "reservas") return <ReservationsPanel {...p} />; if (tab === "bloqueios") return <BlocksPanel {...p} />; if (tab === "relatorios") return <ReportsPanel {...p} />; if (tab === "localizacao") return <LocationPanel {...p} />; if (tab === "emprestimos" || tab === "devolucoes") return <LoansPanel {...p} mode={tab} />; if (["autores", "editoras", "categorias"].includes(tab)) return <EntityPanel {...p} kind={tab} />; if (tab === "exemplares") return <CopiesPanel {...p} />; if (tab === "leitores") return <ReadersPanel {...p} />; return <BooksPanel {...p} />; }
function WorkspaceNavigation({ tab, setTab }: { tab: Tab; setTab: (tab: Tab) => void }) { const active = workspaces.find((workspace) => workspace.items.includes(tab)) || workspaces[0]; return <nav className="library-workspace-nav" aria-label="Rotinas da biblioteca"><div className="library-workspace-list">{workspaces.map(({ key, label, description, icon: Icon, items }) => <button key={key} type="button" className={active.key === key ? "is-active" : ""} onClick={() => setTab(items[0])}><span className="library-workspace-icon"><Icon size={17} /></span><span><strong>{label}</strong><small>{description}</small></span></button>)}</div><div className="library-subnav" aria-label={`Seções de ${active.label}`}>{active.items.map((item) => { const option = tabs.find((tabOption) => tabOption.key === item)!; const Icon = option.icon; return <button key={item} type="button" className={tab === item ? "is-active" : ""} onClick={() => setTab(item)}><Icon size={14} /> {option.label}</button>; })}</div></nav>; }
function Header({ title, description, search, setSearch, action, actionLabel }: any) { return <div className="library-toolbar"><div><h2>{title}</h2><p>{description}</p></div><div className="library-toolbar-actions"><label><Search size={15} /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar..." /></label>{action && <button type="button" className="library-primary" onClick={action}><Plus size={15} /> {actionLabel}</button>}</div></div>; }
function Metric({ icon: Icon, value, label, tone }: any) { return <div className={`library-metric library-metric--${tone}`}><span><Icon size={19} /></span><strong>{value}</strong><small>{label}</small></div>; }
function Dashboard(p: any) { const recent = p.loans.slice(0, 6); const today = dayKey(new Date()); const loansToday = p.loans.filter((x: Row) => dayKey(x.data_retirada) === today); const returnsToday = p.loanItems.filter((x: Row) => dayKey(x.data_devolucao) === today); const activeLoans = p.loans.filter((x: Row) => ["ABERTO", "PARCIAL", "ATRASADO"].includes(x.status)); const liveRows = [...loansToday.map((x: Row) => ({ key: `loan-${x.id}`, label: "Empréstimo registrado", detail: `${p.readerName(x.leitor_id)} · ${time(x.data_retirada)}`, tone: "blue" })), ...returnsToday.map((x: Row) => ({ key: `return-${x.id}`, label: "Devolução registrada", detail: `Exemplar #${x.exemplar_id} · ${time(x.data_devolucao)}`, tone: "green" }))].sort((a, b) => b.detail.localeCompare(a.detail)).slice(0, 5); return <section className="library-dashboard"><div className="library-dashboard-card library-dashboard-card--hero"><span className="library-hero-icon"><Library size={28} /></span><div><span className="section-kicker">Visão operacional</span><h2>Biblioteca Municipal</h2><p>Catálogo, atendimento, circulação, inventário e governança em um único módulo.</p></div><ChevronRight size={22} /></div><div className="library-routine-actions"><div><span className="section-kicker">Comece por aqui</span><h3>O que você precisa fazer?</h3></div><div className="library-routine-action-list"><button type="button" onClick={() => p.setTab("emprestimos")}><Users size={16} /><span><strong>Novo atendimento</strong><small>Empréstimo ou consulta de leitor</small></span><ChevronRight size={15} /></button><button type="button" onClick={() => p.setTab("devolucoes")}><Check size={16} /><span><strong>Registrar devolução</strong><small>Encerrar ou atualizar circulação</small></span><ChevronRight size={15} /></button><button type="button" onClick={() => p.setTab("livros")}><BookOpen size={16} /><span><strong>Gerenciar acervo</strong><small>Obras, exemplares e catálogo</small></span><ChevronRight size={15} /></button><button type="button" onClick={() => p.setTab("inventario")}><ClipboardList size={16} /><span><strong>Iniciar inventário</strong><small>Conferir o acervo físico</small></span><ChevronRight size={15} /></button></div></div><div className="library-live-panel"><div className="library-live-heading"><div><span className="section-kicker">Monitoramento do dia</span><h3>Circulação em tempo real</h3><p>Atualização automática quando há uma nova retirada ou devolução.</p></div><span className="library-live-status"><i /> Ao vivo</span></div><div className="library-live-grid"><LiveMetric icon={ChevronRight} value={loansToday.length} label="Empréstimos hoje" tone="blue" /><LiveMetric icon={Check} value={returnsToday.length} label="Devoluções hoje" tone="green" /><LiveMetric icon={BookOpen} value={activeLoans.length} label="Em circulação" tone="purple" /></div><div className="library-live-activity">{liveRows.length ? liveRows.map((row) => <div className="library-live-row" key={row.key}><span className={`library-live-dot library-live-dot--${row.tone}`} /><span><strong>{row.label}</strong><small>{row.detail}</small></span></div>) : <span className="library-muted">Nenhuma movimentação registrada hoje.</span>}</div></div><div className="library-shortcuts"><Shortcut icon={BookOpen} title="Catálogo" value={`${p.activeBooks.length} obras ativas`} /><Shortcut icon={Users} title="Atendimento" value={`${p.activeReaders.length} leitores ativos`} /><Shortcut icon={BarChart3} title="Circulação" value={`${p.loans.length} empréstimos`} /><Shortcut icon={CircleAlert} title="Atenção" value={`${p.overdue.length} atrasados`} /></div><div className="library-dashboard-grid"><div className="library-dashboard-card"><div className="library-card-heading"><div><span className="section-kicker">Movimentações</span><h3>Empréstimos recentes</h3></div></div>{recent.length ? recent.map((x: Row) => <div className="library-activity" key={x.id}><span className="activity-dot" /><div><strong>{p.readerName(x.leitor_id)}</strong><small>{x.codigo || `#${x.id}`} · prazo {date(x.prazo_devolucao)}</small></div><span className="library-pill library-pill--blue">{statusLabel(x.status)}</span></div>) : <p className="library-muted">Nenhum empréstimo registrado.</p>}</div><div className="library-dashboard-card"><div className="library-card-heading"><div><span className="section-kicker">Acervo físico</span><h3>Disponibilidade</h3></div><BookOpen size={19} /></div><div className="library-progress-row"><span>Exemplares disponíveis</span><strong>{p.available.length} / {p.copies.length}</strong></div><div className="library-progress"><i style={{ width: `${p.copies.length ? Math.round(p.available.length / p.copies.length * 100) : 0}%` }} /></div><p className="library-muted">O inventário e a localização física podem ser acessados nas abas específicas.</p></div></div></section>; }
function LiveMetric(p: any) { const Icon = p.icon; return <div className={`library-live-metric library-live-metric--${p.tone}`}><span><Icon size={17} /></span><strong>{p.value}</strong><small>{p.label}</small></div>; }
function Shortcut({ icon: Icon, title, value }: any) { return <div className="library-shortcut"><span><Icon size={18} /></span><div><strong>{title}</strong><small>{value}</small></div></div>; }
function Pagination({ page, total, onChange, pageSize = 25 }: { page: number; total: number; onChange: (page: number) => void; pageSize?: number }) { const pages = Math.max(1, Math.ceil(total / pageSize)); if (total <= pageSize) return null; return <div className="library-pagination"><span>Mostrando {(page - 1) * pageSize + 1}–{Math.min(page * pageSize, total)} de {total}</span><div><button type="button" disabled={page === 1} onClick={() => onChange(page - 1)}>Anterior</button><strong>Página {page} de {pages}</strong><button type="button" disabled={page === pages} onClick={() => onChange(page + 1)}>Próxima</button></div></div>; }
function BooksPanel(p: any) { const [page, setPage] = useState(1); const filtered = p.books.filter((x: Row) => `${x.titulo} ${x.isbn || ""}`.toLowerCase().includes(p.search.toLowerCase())); const rows = filtered.slice((page - 1) * 25, page * 25); return <section className="library-panel"><Header title="Catálogo bibliográfico" description="Obras, dados bibliográficos, editora, autores, categorias e status." search={p.search} setSearch={p.setSearch} action={p.openNew} actionLabel="Novo livro" />{p.form === "livros" && <LibraryModal onClose={() => p.setForm(null)}><BookForm {...p} /></LibraryModal>}{rows.length ? <div className="library-card-grid">{rows.map((x: Row) => <article className="library-record-card" key={x.id}><div className="record-icon record-icon--purple"><BookOpen size={21} /></div><div className="record-body"><span className="record-chip">#{x.id} · {x.ativo === false ? "Inativo" : "Ativo"}</span><h3>{x.titulo}</h3><p>{[x.subtitulo, x.isbn && `ISBN ${x.isbn}`, x.ano_publicacao, x.idioma].filter(Boolean).join(" · ") || "Sem dados complementares"}</p></div><div className="record-actions"><button type="button" onClick={() => { p.setEditing(x); p.setForm("livros"); }}><Edit3 size={15} /> Editar</button><button type="button" onClick={() => void p.toggle("bib_livros", x)}> {x.ativo === false ? "Reativar" : "Inativar"}</button></div></article>)}</div> : <Empty label="Nenhum livro encontrado" action={p.openNew} />}<Pagination page={page} total={filtered.length} onChange={setPage} /></section>; }
function BookForm(p: any) { const x = p.editing || {}; return <form className="library-form" onSubmit={p.submitBook}><div className="library-form-head"><div><span className="section-kicker">Catálogo completo</span><h3>{p.editing ? "Editar livro" : "Novo livro"}</h3></div><button type="button" onClick={() => p.setForm(null)}><X size={16} /></button></div><div className="library-form-grid"><label>Título *<input required name="titulo" defaultValue={x.titulo || ""} /></label><label>Subtítulo<input name="subtitulo" defaultValue={x.subtitulo || ""} /></label><label>ISBN<input name="isbn" defaultValue={x.isbn || ""} /></label><label>Editora<select name="editora_id" defaultValue={x.editora_id || ""}><option value="">Não informada</option>{p.publishers.map((v: Row) => <option key={v.id} value={v.id}>{v.nome}</option>)}</select></label><label>Ano<input name="ano" type="number" min="0" defaultValue={x.ano_publicacao || ""} /></label><label>Edição<input name="edicao" defaultValue={x.edicao || ""} /></label><label>Idioma<input name="idioma" defaultValue={x.idioma || "Português"} /></label><label>Páginas<input name="paginas" type="number" min="0" defaultValue={x.numero_paginas || ""} /></label><label className="library-form-wide">Sinopse<textarea name="sinopse" defaultValue={x.sinopse || ""} /></label><label>Autores *<select multiple required name="autor_id" defaultValue={p.bookAuthors.filter((v: Row) => v.livro_id === x.id).map((v: Row) => String(v.autor_id))} size={4}>{p.authors.filter((v: Row) => v.ativo !== false).map((v: Row) => <option key={v.id} value={v.id}>{v.nome}</option>)}</select></label><label>Categorias<select multiple name="categoria_id" defaultValue={p.bookCategories.filter((v: Row) => v.livro_id === x.id).map((v: Row) => String(v.categoria_id))} size={4}>{p.categories.filter((v: Row) => v.ativo !== false).map((v: Row) => <option key={v.id} value={v.id}>{v.nome}</option>)}</select></label></div>{x.id && <AttachmentPanel {...p} entity="LIVRO" entityId={x.id} />}<div className="library-form-actions"><button type="button" onClick={() => p.setForm(null)}>Cancelar</button><button className="library-primary" disabled={p.busy} type="submit"><Check size={15} /> Salvar livro</button></div></form>; }
function ReadersPanel(p: any) { const [selectedReader, setSelectedReader] = useState<Row | null>(null); const [page, setPage] = useState(1); const filtered = p.readers.filter((x: Row) => `${x.nome} ${x.cpf || ""} ${x.email || ""}`.toLowerCase().includes(p.search.toLowerCase())); const rows = filtered.slice((page - 1) * 25, page * 25); return <section className="library-panel"><Header title="Leitores e atendimento" description="Cadastro completo, status de circulação e identificação dos leitores." search={p.search} setSearch={p.setSearch} action={p.openNew} actionLabel="Novo leitor" />{p.form === "leitores" && <LibraryModal onClose={() => p.setForm(null)}><ReaderForm {...p} /></LibraryModal>}{selectedReader && <LibraryModal onClose={() => setSelectedReader(null)}><Reader360 reader={selectedReader} {...p} close={() => setSelectedReader(null)} /></LibraryModal>}{rows.length ? <Table headers={["Leitor", "Tipo", "Contato", "Situação", "Ações"]}>{rows.map((x: Row) => <tr key={x.id}><td><strong>{x.nome}</strong><small>{x.cpf || x.codigo_carteirinha || "Sem documento informado"}</small></td><td><span className="library-pill library-pill--blue">{x.tipo_leitor || "—"}</span></td><td>{x.email || x.telefone || "—"}</td><td><span className={`library-pill ${x.status === "ATIVO" ? "library-pill--green" : x.status === "SUSPENSO" ? "library-pill--red" : "library-pill--gray"}`}>{statusLabel(x.status)}</span></td><td className="table-actions"><button type="button" className="library-attendance-button" onClick={() => { setSelectedReader(x); p.setInitialReaderId(x.id); }}><UserRound size={14} /> Atendimento 360°</button><button type="button" onClick={() => { p.setEditing(x); p.setForm("leitores"); }}><Edit3 size={14} /></button><button type="button" onClick={() => void p.toggle("bib_leitores", x, "status")}>{x.status === "ATIVO" ? "Inativar" : "Reativar"}</button></td></tr>)}</Table> : <Empty label="Nenhum leitor encontrado" action={p.openNew} />}<Pagination page={page} total={filtered.length} onChange={setPage} /></section>; }
function Reader360(p: any) { const reader = p.reader; const loans = p.loans.filter((x: Row) => x.leitor_id === reader.id); const active = loans.filter((x: Row) => ["ABERTO", "PARCIAL", "ATRASADO"].includes(x.status)); const overdue = loans.filter((x: Row) => p.overdue.some((o: Row) => o.id === x.id)); const reservations = p.reservations.filter((x: Row) => x.leitor_id === reader.id); const blocks = p.blocks.filter((x: Row) => x.leitor_id === reader.id && x.ativo); const returns = p.loanItems.filter((item: Row) => loans.some((loan: Row) => loan.id === item.emprestimo_id) && item.data_devolucao).slice(-5).reverse(); const go = (tab: Tab, form?: Tab) => { p.close(); if (form) p.setInitialReaderId(reader.id); p.setTab(tab); if (form) { p.setEditing(null); p.setForm(form); } }; return <div className="library-reader360"><div className="library-reader360-head"><div className="library-reader-avatar"><UserRound size={24} /></div><div><span className="section-kicker">Atendimento 360°</span><h2>{reader.nome}</h2><p>{reader.codigo_carteirinha || reader.cpf || "Leitor sem documento informado"} · {reader.tipo_leitor || "Comunidade"}</p></div><span className={`library-pill ${reader.status === "ATIVO" ? "library-pill--green" : "library-pill--red"}`}>{statusLabel(reader.status)}</span></div><div className="library-reader360-actions"><button type="button" className="library-primary" onClick={() => go("emprestimos", "emprestimos")}><BookOpen size={15} /> Novo empréstimo</button><button type="button" onClick={() => go("devolucoes")}><Check size={15} /> Registrar devolução</button><button type="button" onClick={() => go("reservas")}><RefreshCw size={15} /> Ver reservas</button><button type="button" onClick={() => go("leitores")}><Edit3 size={15} /> Editar leitor</button></div><div className="library-reader360-metrics"><Metric icon={BookOpen} value={active.length} label="Em circulação" tone="purple" /><Metric icon={CircleAlert} value={overdue.length} label="Em atraso" tone="orange" /><Metric icon={RefreshCw} value={reservations.length} label="Reservas" tone="blue" /><Metric icon={Shield} value={blocks.length} label="Bloqueios ativos" tone="red" /></div><div className="library-reader360-grid"><section><div className="library-card-heading"><div><span className="section-kicker">Circulação</span><h3>Empréstimos do leitor</h3></div></div>{loans.length ? loans.slice(0, 6).map((loan: Row) => <div className="library-reader360-row" key={loan.id}><span className={`library-live-dot ${overdue.some((x: Row) => x.id === loan.id) ? "library-live-dot--red" : "library-live-dot--blue"}`} /><span><strong>{loan.codigo || `Empréstimo #${loan.id}`}</strong><small>{date(loan.data_retirada)} · prazo {date(loan.prazo_devolucao)}</small></span><span className="library-pill library-pill--blue">{statusLabel(overdue.some((x: Row) => x.id === loan.id) ? "ATRASADO" : loan.status)}</span></div>) : <p className="library-muted">Nenhum empréstimo registrado.</p>}</section><section><div className="library-card-heading"><div><span className="section-kicker">Histórico</span><h3>Últimas devoluções</h3></div></div>{returns.length ? returns.map((item: Row) => <div className="library-reader360-row" key={item.id}><span className="library-live-dot library-live-dot--green" /><span><strong>Exemplar #{item.exemplar_id}</strong><small>Devolvido em {date(item.data_devolucao)}</small></span><Check size={15} color="#3eae82" /></div>) : <p className="library-muted">Nenhuma devolução registrada.</p>}</section></div>{blocks.length > 0 && <div className="library-reader-alert"><CircleAlert size={18} /><span><strong>Leitor com bloqueio ativo.</strong><small>{blocks[0].motivo || "Regularize o bloqueio antes de uma nova circulação."}</small></span><button type="button" onClick={() => go("bloqueios")}>Ver bloqueio</button></div>}</div>; }
function ReaderForm(p: any) { const x = p.editing || {}; return <form className="library-form" onSubmit={p.submitReader}><div className="library-form-head"><div><span className="section-kicker">Atendimento</span><h3>{p.editing ? "Editar leitor" : "Novo leitor"}</h3></div><button type="button" onClick={() => p.setForm(null)}><X size={16} /></button></div><div className="library-form-grid"><label>Nome completo *<input required name="nome" defaultValue={x.nome || ""} /></label><label>CPF<input name="cpf" defaultValue={x.cpf || ""} /></label><label>Carteirinha<input name="carteirinha" defaultValue={x.codigo_carteirinha || ""} /></label><label>E-mail<input name="email" type="email" defaultValue={x.email || ""} /></label><label>Telefone<input name="telefone" defaultValue={x.telefone || ""} /></label><label>Tipo<select name="tipo" defaultValue={x.tipo_leitor || "COMUNIDADE"}><option>COMUNIDADE</option><option>ESTUDANTE</option><option>SERVIDOR</option><option>PROFESSOR</option></select></label><label>Situação<select name="status" defaultValue={x.status || "ATIVO"}><option>ATIVO</option><option>SUSPENSO</option><option>INATIVO</option></select></label></div>{x.id && <AttachmentPanel {...p} entity="LEITOR" entityId={x.id} />}<div className="library-form-actions"><button type="button" onClick={() => p.setForm(null)}>Cancelar</button><button className="library-primary" disabled={p.busy} type="submit"><Check size={15} /> Salvar leitor</button></div></form>; }
function EntityPanel(p: any) { const map: any = { autores: ["Autores", "bib_autores", p.authors, "nome", "nacionalidade"], editoras: ["Editoras", "bib_editoras", p.publishers, "nome", "cidade"], categorias: ["Categorias", "bib_categorias", p.categories, "nome", "descricao"] }; const [title, table, rows, primary, secondary] = map[p.kind]; const [page, setPage] = useState(1); const filtered = rows.filter((x: Row) => `${x[primary]} ${x[secondary] || ""}`.toLowerCase().includes(p.search.toLowerCase())); return <section className="library-panel"><Header title={title} description="Cadastro, edição, ativação e preservação do histórico." search={p.search} setSearch={p.setSearch} action={p.openNew} actionLabel={`Novo ${title.slice(0, -1).toLowerCase()}`} />{p.form === p.kind && <LibraryModal onClose={() => p.setForm(null)}><SimpleForm {...p} table={table} kind={p.kind} fields={p.kind === "autores" ? ["nome", "nacionalidade", "biografia"] : p.kind === "editoras" ? ["nome", "cidade", "uf"] : ["nome", "descricao", "cor"]} /></LibraryModal>}{filtered.length ? <Table headers={["Nome", "Informações", "Status", "Ações"]}>{filtered.map((x: Row) => <tr key={x.id}><td><strong>{x[primary]}</strong><small>#{x.id}</small></td><td>{x[secondary] || "—"}</td><td><span className={`library-pill ${x.ativo === false ? "library-pill--gray" : "library-pill--green"}`}>{x.ativo === false ? "INATIVO" : "ATIVO"}</span></td><td className="table-actions"><button type="button" onClick={() => { p.setEditing(x); p.setForm(p.kind); }}><Edit3 size={14} /> Editar</button><button type="button" onClick={() => void p.toggle(table, x)}> {x.ativo === false ? "Reativar" : "Inativar"}</button></td></tr>)}</Table> : <Empty label={`Nenhum registro em ${title.toLowerCase()}`} action={p.openNew} />}<Pagination page={page} total={filtered.length} onChange={setPage} /></section>; }
function SimpleForm(p: any) { const x = p.editing || {}; return <form className="library-form" onSubmit={(e: any) => { e.preventDefault(); const d = new FormData(e.currentTarget); const payload: Row = { ativo: x.ativo !== false }; p.fields.forEach((f: string) => payload[f] = String(d.get(f) || "").trim() || null); void p.save(p.table, payload, x.id); }}><div className="library-form-head"><h3>{p.editing ? "Editar cadastro" : "Novo cadastro"}</h3><button type="button" onClick={() => p.setForm(null)}><X size={16} /></button></div><div className="library-form-grid">{p.fields.map((f: string) => <label key={f}>{f.replace("_", " ")}<input name={f} required={f === "nome"} defaultValue={x[f] || ""} /></label>)}</div><div className="library-form-actions"><button type="button" onClick={() => p.setForm(null)}>Cancelar</button><button className="library-primary" type="submit" disabled={p.busy}><Check size={15} /> Salvar</button></div></form>; }
function CopiesPanel(p: any) { const [page, setPage] = useState(1); const filtered = p.copies.filter((x: Row) => `${x.codigo} ${p.bookTitle(x.livro_id)} ${x.situacao || ""}`.toLowerCase().includes(p.search.toLowerCase())); const rows = filtered.slice((page - 1) * 25, page * 25); return <section className="library-panel"><Header title="Exemplares físicos" description="Código patrimonial, conservação, situação, aquisição e localização." search={p.search} setSearch={p.setSearch} action={p.openNew} actionLabel="Novo exemplar" />{p.form === "exemplares" && <LibraryModal onClose={() => p.setForm(null)}><SimpleForm {...p} table="bib_exemplares" kind="exemplares" fields={["codigo", "livro_id", "estado_conservacao", "situacao", "observacoes"]} /></LibraryModal>}{rows.length ? <Table headers={["Código", "Obra", "Conservação", "Situação", "Ações"]}>{rows.map((x: Row) => <tr key={x.id}><td><strong>{x.codigo}</strong><small>Exemplar #{x.id}</small></td><td>{p.bookTitle(x.livro_id)}</td><td>{x.estado_conservacao || "—"}</td><td><span className={`library-pill ${x.situacao === "DISPONIVEL" ? "library-pill--green" : "library-pill--orange"}`}>{x.situacao || "—"}</span></td><td><button type="button" onClick={() => { p.setEditing(x); p.setForm("exemplares"); }}><Edit3 size={14} /> Editar</button></td></tr>)}</Table> : <Empty label="Nenhum exemplar encontrado" action={p.openNew} />}<Pagination page={page} total={filtered.length} onChange={setPage} /></section>; }
function LocationPanel(p: any) { return <section className="library-panel"><Header title="Estantes e prateleiras" description="Organização hierárquica da localização física do acervo." search={p.search} setSearch={p.setSearch} /><div className="library-dashboard-grid"><div><h3>Estantes</h3><Table headers={["Código", "Setor", "Status"]}>{p.racks.filter((x: Row) => JSON.stringify(x).toLowerCase().includes(p.search.toLowerCase())).map((x: Row) => <tr key={x.id}><td><strong>{x.codigo || x.nome || `#${x.id}`}</strong></td><td>{x.setor || x.descricao || "—"}</td><td><span className="library-pill library-pill--green">{x.ativo === false ? "INATIVA" : "ATIVA"}</span></td></tr>)}</Table></div><div><h3>Prateleiras</h3><Table headers={["Número", "Estante", "Posição"]}>{p.shelves.filter((x: Row) => JSON.stringify(x).toLowerCase().includes(p.search.toLowerCase())).map((x: Row) => <tr key={x.id}><td><strong>{x.numero || x.codigo || `#${x.id}`}</strong></td><td>{x.estante_id || "—"}</td><td>{x.posicao_inicial || "—"} – {x.posicao_final || "—"}</td></tr>)}</Table></div></div></section>; }
function LoansPanel(p: any) {
  const [page, setPage] = useState(1); const filtered = p.loans.filter((x: Row) => `${x.codigo} ${p.readerName(x.leitor_id)} ${x.status}`.toLowerCase().includes(p.search.toLowerCase())); const rows = filtered.slice((page - 1) * 25, page * 25);
  const registerReturn = async (loan: Row) => { const items = await supabase.from("bib_emprestimo_itens").select("id").eq("emprestimo_id", loan.id).is("data_devolucao", null); if (items.error) return p.setNotice({ kind: "error", text: text(items.error) }); for (const item of items.data || []) { const r = await supabase.from("bib_emprestimo_itens").update({ data_devolucao: new Date().toISOString(), estado_devolucao: "BOM" }).eq("id", item.id); if (r.error) return p.setNotice({ kind: "error", text: text(r.error) }); } p.setNotice({ kind: "ok", text: "Devolução registrada; a situação dos itens foi atualizada." }); await p.load(); };
  const registerLoan = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const d = new FormData(e.currentTarget); const leitorId = Number(d.get("leitor_id")); const selected = Array.from(d.getAll("exemplar_id")).map(Number).filter(Boolean); const days = Number(d.get("dias") || p.config?.prazo_padrao_dias || 14); const usuarioId = Number(p.profile?.id); if (!leitorId || !selected.length) return p.setNotice({ kind: "error", text: "Selecione o leitor e ao menos um exemplar disponível." }); if (!Number.isInteger(usuarioId) || usuarioId <= 0) return p.setNotice({ kind: "error", text: "Não foi possível identificar o usuário municipal responsável pela operação." }); if (!Number.isInteger(days) || days < 1 || days > Number(p.config?.prazo_maximo_dias || 30)) return p.setNotice({ kind: "error", text: `O prazo deve estar entre 1 e ${p.config?.prazo_maximo_dias || 30} dias.` }); const prazo = new Date(); prazo.setDate(prazo.getDate() + days); const created = await supabase.from("bib_emprestimos").insert({ leitor_id: leitorId, usuario_id: usuarioId, data_retirada: new Date().toISOString(), prazo_devolucao: prazo.toISOString().slice(0, 10), status: "ABERTO", renovacoes: 0 }).select("id,codigo").single(); if (created.error) return p.setNotice({ kind: "error", text: text(created.error) }); const items = await supabase.from("bib_emprestimo_itens").insert(selected.map((exemplar_id) => ({ emprestimo_id: created.data.id, exemplar_id }))); if (items.error) { await supabase.from("bib_emprestimos").delete().eq("id", created.data.id); return p.setNotice({ kind: "error", text: `Não foi possível registrar os exemplares; a operação foi desfeita. ${text(items.error)}` }); } p.setNotice({ kind: "ok", text: `Empréstimo ${created.data.codigo || created.data.id} registrado.` }); p.setForm(null); await p.load(); };
  return <section className="library-panel"><Header title={p.mode === "devolucoes" ? "Devoluções" : "Empréstimos"} description="Consulte prazos, atrasos, devoluções parciais e renovações." search={p.search} setSearch={p.setSearch} action={() => { p.setEditing(null); p.setForm(p.mode); }} actionLabel={p.mode === "devolucoes" ? "Registrar devolução" : "Novo empréstimo"} />{p.form === "emprestimos" && <LibraryModal onClose={() => p.setForm(null)}><CirculationFlow {...p} mode="emprestimos" close={() => p.setForm(null)} initialReaderId={p.initialReaderId} /></LibraryModal>}{p.form === "devolucoes" && <LibraryModal onClose={() => p.setForm(null)}><CirculationFlow {...p} mode="devolucoes" close={() => p.setForm(null)} initialReaderId={p.initialReaderId} /></LibraryModal>}<Table headers={["Código", "Leitor", "Retirada", "Prazo", "Status", "Ações"]}>{rows.map((x: Row) => { const late = p.overdue.some((o: Row) => o.id === x.id); return <tr key={x.id}><td><strong>{x.codigo || `#${x.id}`}</strong><small>{x.renovacoes || 0} renovação(ões)</small></td><td>{p.readerName(x.leitor_id)}</td><td>{date(x.data_retirada)}</td><td>{date(x.prazo_devolucao)}</td><td><span className={`library-pill ${late ? "library-pill--red" : x.status === "DEVOLVIDO" ? "library-pill--gray" : "library-pill--blue"}`}>{statusLabel(late ? "ATRASADO" : x.status)}</span></td><td className="table-actions">{["ABERTO", "PARCIAL"].includes(x.status) && <>{p.mode === "emprestimos" && <button type="button" disabled={p.busy} onClick={async () => { const r = await supabase.rpc("bib_renovar_emprestimo", { p_emprestimo_id: x.id }); if (r.error) p.setNotice({ kind: "error", text: text(r.error) }); else { p.setNotice({ kind: "ok", text: "Empréstimo renovado com auditoria." }); await p.load(); } }}><RefreshCw size={14} /> Renovar</button>}{p.mode === "devolucoes" && <button type="button" onClick={() => void registerReturn(x)}><Check size={14} /> Devolver</button>}</>}</td></tr>; })}</Table><Pagination page={page} total={filtered.length} onChange={setPage} /></section>;
  }
function CirculationFlow(p: any) { const isLoan = p.mode === "emprestimos"; const initialLoan = !isLoan && p.initialReaderId ? p.loans.find((x: Row) => x.leitor_id === p.initialReaderId && ["ABERTO", "PARCIAL", "ATRASADO"].includes(x.status)) : null; const [step, setStep] = useState(1); const [readerId, setReaderId] = useState<number | null>(p.initialReaderId || null); const [copyIds, setCopyIds] = useState<number[]>([]); const [loanId, setLoanId] = useState<number | null>(initialLoan?.id || null); const [itemIds, setItemIds] = useState<number[]>([]); const [days, setDays] = useState(Number(p.config?.prazo_padrao_dias || 14)); const reader = p.readers.find((x: Row) => x.id === readerId); const readerLoans = p.loans.filter((x: Row) => x.leitor_id === readerId); const activeLoans = readerLoans.filter((x: Row) => ["ABERTO", "PARCIAL", "ATRASADO"].includes(x.status)); const blocked = p.blocks.some((x: Row) => x.leitor_id === readerId && x.ativo && (!x.fim || new Date(x.fim) >= new Date())); const overdue = readerLoans.filter((x: Row) => p.overdue.some((o: Row) => o.id === x.id)); const selectedLoan = p.loans.find((x: Row) => x.id === loanId); const pendingItems = p.loanItems.filter((x: Row) => x.emprestimo_id === loanId && !x.data_devolucao); const eligibleCopies = p.available.filter((x: Row) => !p.reservations.some((r: Row) => r.exemplar_id === x.id && ["ATIVA", "PENDENTE"].includes(r.status))); const next = () => { if (isLoan && step === 1 && (!readerId || blocked || overdue.length || activeLoans.length >= Number(p.config?.limite_livros_por_leitor || 3))) return; if (isLoan && step === 2 && !copyIds.length) return; if (!isLoan && step === 1 && !loanId) return; setStep((value) => value + 1); }; const finishLoan = async () => { const prazo = new Date(); prazo.setDate(prazo.getDate() + days); const created = await supabase.from("bib_emprestimos").insert({ leitor_id: readerId, usuario_id: Number(p.profile?.id), data_retirada: new Date().toISOString(), prazo_devolucao: prazo.toISOString().slice(0, 10), status: "ABERTO", renovacoes: 0 }).select("id,codigo").single(); if (created.error) return p.setNotice({ kind: "error", text: text(created.error) }); const items = await supabase.from("bib_emprestimo_itens").insert(copyIds.map((exemplar_id) => ({ emprestimo_id: created.data.id, exemplar_id }))); if (items.error) { await supabase.from("bib_emprestimos").delete().eq("id", created.data.id); return p.setNotice({ kind: "error", text: `Operação desfeita: ${text(items.error)}` }); } p.close(); p.setNotice({ kind: "ok", text: `Empréstimo ${created.data.codigo || created.data.id} registrado com sucesso.` }); await p.load(); }; const finishReturn = async () => { const ids = itemIds.length ? itemIds : pendingItems.map((x: Row) => x.id); for (const id of ids) { const result = await supabase.from("bib_emprestimo_itens").update({ data_devolucao: new Date().toISOString(), estado_devolucao: "BOM" }).eq("id", id); if (result.error) return p.setNotice({ kind: "error", text: text(result.error) }); } p.close(); p.setNotice({ kind: "ok", text: `${ids.length} item(ns) devolvido(s) com sucesso.` }); await p.load(); }; const canAdvance = isLoan ? (step === 1 ? Boolean(readerId && !blocked && !overdue.length && activeLoans.length < Number(p.config?.limite_livros_por_leitor || 3)) : step === 2 ? copyIds.length > 0 : days >= 1 && days <= Number(p.config?.prazo_maximo_dias || 30)) : (step === 1 ? Boolean(loanId) : step === 2 ? itemIds.length > 0 : true); return <div className="library-flow"><div className="library-form-head"><div><span className="section-kicker">Atendimento · {isLoan ? "Novo empréstimo" : "Registrar devolução"}</span><h3>{isLoan ? "Fluxo guiado de empréstimo" : "Fluxo guiado de devolução"}</h3></div><button type="button" onClick={p.close}><X size={16} /></button></div><div className="library-flow-steps"><span className={step >= 1 ? "is-active" : ""}>1. {isLoan ? "Leitor" : "Empréstimo"}</span><span className={step >= 2 ? "is-active" : ""}>2. {isLoan ? "Exemplares" : "Itens"}</span><span className={step >= 3 ? "is-active" : ""}>3. Confirmar</span></div>{step === 1 && isLoan && <div className="library-flow-content"><label className="library-flow-label">Selecione o leitor<select value={readerId || ""} disabled={Boolean(p.initialReaderId)} onChange={(e) => setReaderId(Number(e.target.value) || null)}><option value="">Escolha um leitor ativo</option>{p.activeReaders.map((x: Row) => <option key={x.id} value={x.id}>{x.nome} · {x.codigo_carteirinha || x.cpf || `#${x.id}`}</option>)}</select></label>{reader && <div className="library-flow-reader-summary"><strong>{reader.nome}</strong><span>{activeLoans.length} empréstimo(s) ativo(s) · {overdue.length} atraso(s) · limite {p.config?.limite_livros_por_leitor || 3}</span></div>}{reader && (blocked || overdue.length || activeLoans.length >= Number(p.config?.limite_livros_por_leitor || 3)) && <div className="library-flow-warning"><CircleAlert size={17} /><span><strong>Operação não pode avançar</strong><small>{blocked ? "O leitor possui bloqueio ativo." : overdue.length ? "Regularize os empréstimos em atraso." : "O limite de empréstimos foi atingido."}</small></span></div>}</div>}{step === 1 && !isLoan && <div className="library-flow-content"><label className="library-flow-label">Selecione o empréstimo<select value={loanId || ""} onChange={(e) => { setLoanId(Number(e.target.value) || null); setItemIds([]); }}><option value="">Escolha um empréstimo em aberto</option>{p.loans.filter((x: Row) => ["ABERTO", "PARCIAL", "ATRASADO"].includes(x.status)).map((x: Row) => <option key={x.id} value={x.id}>{x.codigo || `#${x.id}`} · {p.readerName(x.leitor_id)} · {statusLabel(x.status)}</option>)}</select></label>{selectedLoan && <div className="library-flow-reader-summary"><strong>{p.readerName(selectedLoan.leitor_id)}</strong><span>Prazo: {date(selectedLoan.prazo_devolucao)} · {pendingItems.length} item(ns) pendente(s)</span></div>}</div>}{step === 2 && isLoan && <div className="library-flow-content"><label className="library-flow-label">Escolha os exemplares disponíveis<select multiple value={copyIds.map(String)} onChange={(e) => setCopyIds(Array.from(e.target.selectedOptions).map((option) => Number(option.value)))} size={Math.min(8, Math.max(4, eligibleCopies.length))}>{eligibleCopies.map((x: Row) => <option key={x.id} value={x.id}>{x.codigo} · {p.bookTitle(x.livro_id)}</option>)}</select></label><p className="library-muted">Somente exemplares disponíveis e não reservados aparecem nesta lista.</p></div>}{step === 2 && !isLoan && <div className="library-flow-content"><p className="library-flow-label">Selecione os itens que serão devolvidos</p>{pendingItems.map((item: Row) => <label className="library-flow-check" key={item.id}><input type="checkbox" checked={itemIds.includes(item.id)} onChange={(e) => setItemIds((current) => e.target.checked ? [...current, item.id] : current.filter((id) => id !== item.id))} /> Exemplar #{item.exemplar_id}</label>)}<button type="button" className="library-flow-link" onClick={() => setItemIds(pendingItems.map((x: Row) => x.id))}>Selecionar todos</button></div>}{step === 3 && <div className="library-flow-content"><div className="library-flow-review"><span><strong>{isLoan ? "Leitor" : "Empréstimo"}</strong>{isLoan ? reader?.nome : `${p.readerName(selectedLoan?.leitor_id)} · ${selectedLoan?.codigo || `#${selectedLoan?.id}`}`}</span><span><strong>{isLoan ? "Itens" : "Devolução"}</strong>{isLoan ? `${copyIds.length} exemplar(es)` : `${itemIds.length} item(ns) · estado: bom`}</span>{isLoan && <label><strong>Prazo</strong><input type="number" min="1" max={p.config?.prazo_maximo_dias || 30} value={days} onChange={(e) => setDays(Number(e.target.value))} /> dias</label>}</div><p className="library-muted">Revise os dados antes de confirmar. A operação será registrada com histórico e atualizará a situação da circulação.</p></div>}<div className="library-form-actions">{step > 1 && <button type="button" onClick={() => setStep((value) => value - 1)}>Voltar</button>}<button type="button" onClick={step === 3 ? (isLoan ? finishLoan : finishReturn) : next} className="library-primary" disabled={!canAdvance}>{step === 3 ? <><Check size={15} /> Confirmar operação</> : <>Continuar <ChevronRight size={15} /></>}</button></div></div>; }
function AttachmentPanel(p: any) { const rows = p.documents.filter((x: Row) => x.entidade === p.entity && String(x.entidade_id) === String(p.entityId)); const upload = async (e: any) => { const file = e.currentTarget.files?.[0]; e.currentTarget.value = ""; if (!file) return; if (!p.canManage) return p.setNotice({ kind: "error", text: "Seu perfil não pode anexar documentos." }); if (file.size > 26214400) return p.setNotice({ kind: "error", text: "O limite de anexos é 25 MB." }); const allowed = ["application/pdf", "image/png", "image/jpeg", "image/webp", "application/msword", "application/vnd.openxmlformats-officedocument.wordprocessingml.document", "application/vnd.oasis.opendocument.text"]; if (!allowed.includes(file.type)) return p.setNotice({ kind: "error", text: "Tipo de arquivo não permitido." }); const safe = file.name.toLowerCase().replace(/[^a-z0-9._-]+/g, "-"); const path = `${p.entity.toLowerCase()}/${p.entityId}/${crypto.randomUUID()}-${safe}`; const up = await supabase.storage.from("biblioteca-documentos").upload(path, file, { contentType: file.type, upsert: false }); if (up.error) return p.setNotice({ kind: "error", text: text(up.error) }); const reg = await supabase.rpc("bib_registrar_documento", { p_entidade: p.entity, p_entidade_id: String(p.entityId), p_nome_arquivo: file.name, p_storage_path: path, p_mime_type: file.type, p_tamanho_bytes: file.size }); if (reg.error) { await supabase.storage.from("biblioteca-documentos").remove([path]); return p.setNotice({ kind: "error", text: text(reg.error) }); } p.setNotice({ kind: "ok", text: "Documento anexado e auditado." }); await p.load(); }; return <div className="library-attachments"><div className="library-card-heading"><div><span className="section-kicker">Documentos e anexos</span><h4>Anexos desta entidade</h4></div><label className="library-primary library-upload"><Plus size={14} /> Anexar<input type="file" hidden onChange={upload} /></label></div>{rows.length ? rows.map((x: Row) => <div className="library-attachment" key={x.id}><FileText size={15} /><span><strong>{x.nome_arquivo}</strong><small>{Math.round((x.tamanho_bytes || 0) / 1024)} KB · {date(x.created_at)}</small></span><button type="button" onClick={async () => { const r = await supabase.storage.from("biblioteca-documentos").createSignedUrl(x.storage_path, 300); if (r.error) p.setNotice({ kind: "error", text: text(r.error) }); else window.open(r.data.signedUrl, "_blank", "noopener,noreferrer"); }}>Abrir</button></div>) : <p className="library-muted">Nenhum documento anexado.</p>}</div>; }
function BlocksPanel(p: any) { const [page, setPage] = useState(1); const filtered = p.blocks.filter((x: Row) => JSON.stringify(x).toLowerCase().includes(p.search.toLowerCase())); const rows = filtered.slice((page - 1) * 25, page * 25); const active = p.blocks.filter((x: Row) => x.ativo && (!x.fim || new Date(x.fim) >= new Date())); const candidates = () => { const counts: Row = {}; p.overdue.forEach((x: Row) => { counts[x.leitor_id] = (counts[x.leitor_id] || 0) + 1; }); const overdueReaders = Object.entries(counts).filter(([leitorId]) => !active.some((x: Row) => String(x.leitor_id) === String(leitorId))).map(([leitorId, count]) => ({ reader: p.readers.find((x: Row) => String(x.id) === String(leitorId)), reason: `${count} empréstimo(s) em atraso` })); const suspendedReaders = p.readers.filter((reader: Row) => reader.status === "SUSPENSO" && !active.some((x: Row) => x.leitor_id === reader.id)).map((reader: Row) => ({ reader, reason: "Leitor suspenso por infração" })); return [...overdueReaders, ...suspendedReaders]; }; const automatic = async () => { if (!p.canManage) return p.setNotice({ kind: "error", text: "Seu perfil não pode aplicar bloqueios." }); const affected = candidates(); let created = 0; for (const { reader, reason } of affected) { if (!reader) continue; const r = await supabase.rpc("bib_registrar_bloqueio", { p_leitor_id: reader.id, p_motivo: `Bloqueio automático: ${reason}`, p_fim: null }); if (!r.error) created++; } p.setNotice({ kind: "ok", text: `${created} bloqueio(s) automático(s) criado(s).` }); await p.load(); }; const requestAutomatic = () => { if (!p.canManage) return p.setNotice({ kind: "error", text: "Seu perfil não pode aplicar bloqueios." }); const affected = candidates(); if (!affected.length) return p.setNotice({ kind: "ok", text: "Nenhum leitor precisa de novo bloqueio automático." }); const names = affected.slice(0, 5).map(({ reader }) => reader?.nome || "Leitor não identificado").join(", "); const more = affected.length > 5 ? ` e mais ${affected.length - 5}` : ""; p.setConfirm({ title: "Reaplicar bloqueios automáticos?", message: `${affected.length} leitor(es) serão afetados: ${names}${more}. Serão considerados empréstimos em atraso e leitores suspensos sem bloqueio vigente. Deseja continuar?`, action: automatic }); }; const resolve = async (id: any) => { if (!p.canManage) return p.setNotice({ kind: "error", text: "Seu perfil não pode resolver bloqueios." }); const r = await supabase.rpc("bib_resolver_bloqueio", { p_bloqueio_id: id, p_motivo: "Regularização registrada no atendimento" }); if (r.error) p.setNotice({ kind: "error", text: text(r.error) }); else { p.setNotice({ kind: "ok", text: "Bloqueio resolvido." }); await p.load(); } }; return <section className="library-panel"><Header title="Bloqueios e regras de circulação" description="Bloqueios automáticos para atrasos e infrações, com resolução auditada." search={p.search} setSearch={p.setSearch} action={requestAutomatic} actionLabel="Reaplicar bloqueios automáticos" /><p className="library-muted">A rotina identifica leitores com empréstimos em atraso e leitores suspensos. Nenhum bloqueio é criado ao abrir esta tela; use a ação manual para revisar e confirmar os leitores afetados.</p><Table headers={["Leitor", "Motivo", "Início", "Fim", "Status", "Ações"]}>{rows.map((x: Row) => <tr key={x.id}><td>{p.readerName(x.leitor_id)}</td><td>{x.motivo}</td><td>{date(x.inicio || x.created_at)}</td><td>{date(x.fim)}</td><td><span className={`library-pill ${x.ativo ? "library-pill--red" : "library-pill--gray"}`}>{x.ativo ? "ATIVO" : "RESOLVIDO"}</span></td><td>{x.ativo && <button type="button" onClick={() => void resolve(x.id)}>Resolver</button>}</td></tr>)}</Table><Pagination page={page} total={filtered.length} onChange={setPage} /></section>; }
function ReservationsPanel(p: any) { const [page, setPage] = useState(1); const filtered = p.reservations.filter((x: Row) => JSON.stringify(x).toLowerCase().includes(p.search.toLowerCase())); const rows = filtered.slice((page - 1) * 25, page * 25); return <section className="library-panel"><Header title="Reservas" description="Fila de reservas com controle de disponibilidade e bloqueios." search={p.search} setSearch={p.setSearch} /><Table headers={["Livro", "Leitor", "Status", "Criada em", "Observações"]}>{rows.map((x: Row) => <tr key={x.id}><td>{p.bookTitle(x.livro_id)}</td><td>{p.readerName(x.leitor_id)}</td><td><span className="library-pill library-pill--blue">{statusLabel(x.status)}</span></td><td>{date(x.created_at)}</td><td>{x.observacoes || "—"}</td></tr>)}</Table><Pagination page={page} total={filtered.length} onChange={setPage} /><p className="library-muted">As reservas respeitam as regras da biblioteca, a situação do leitor e a disponibilidade do acervo.</p></section>; }
function InventoryPanel(p: any) { const [selectedId, setSelectedId] = useState<number | null>(null); const [page, setPage] = useState(1); const active = p.inventories.find((x: Row) => x.id === selectedId); const items = p.inventoryItems.filter((x: Row) => x.inventario_id === selectedId); const visibleItems = items.slice((page - 1) * 25, page * 25); const read = items.filter((x: Row) => x.lido_em); const missing = items.filter((x: Row) => !x.lido_em); const start = async () => { const r = await supabase.rpc("bib_iniciar_inventario", { p_nome: `Inventário físico ${new Date().toLocaleDateString("pt-BR")}`, p_escopo: {} }); if (r.error) p.setNotice({ kind: "error", text: text(r.error) }); else { p.setNotice({ kind: "ok", text: "Inventário iniciado com todos os exemplares ativos." }); await p.load(); } }; const scan = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const d = new FormData(e.currentTarget); const codigo = String(d.get("codigo") || "").trim(); if (!active || !codigo) return; const r = await supabase.rpc("bib_registrar_leitura_inventario", { p_inventario_id: active.id, p_codigo: codigo, p_observacao: String(d.get("observacao") || "").trim() || null }); if (r.error) p.setNotice({ kind: "error", text: text(r.error) }); else { p.setNotice({ kind: "ok", text: `Exemplar ${codigo} conferido.` }); e.currentTarget.reset(); await p.load(); } }; const finish = async () => { if (!active) return; const r = await supabase.rpc("bib_concluir_inventario", { p_inventario_id: active.id, p_observacao: `Conferência concluída: ${read.length} de ${items.length} itens lidos.` }); if (r.error) p.setNotice({ kind: "error", text: text(r.error) }); else { p.setNotice({ kind: "ok", text: "Inventário concluído e registrado no histórico." }); setSelectedId(null); await p.load(); } }; const requestFinish = () => { if (!active) return; p.setConfirm({ title: "Concluir inventário?", message: missing.length ? `Há ${missing.length} exemplar(es) ainda pendente(s). Deseja concluir mesmo assim?` : "Todos os exemplares foram conferidos. Deseja concluir este inventário?", action: finish }); }; const cancel = async () => { if (!active) return; const r = await supabase.rpc("bib_cancelar_inventario", { p_inventario_id: active.id, p_motivo: "Cancelado pelo operador no módulo" }); if (r.error) p.setNotice({ kind: "error", text: text(r.error) }); else { p.setNotice({ kind: "ok", text: "Inventário cancelado." }); setSelectedId(null); await p.load(); } }; const requestCancel = () => { if (!active) return; p.setConfirm({ title: "Cancelar inventário?", message: "A conferência será encerrada e permanecerá registrada no histórico. Deseja continuar?", action: cancel }); }; return <section className="library-panel"><Header title="Inventário físico" description="Abra uma conferência, leia os códigos dos exemplares e acompanhe divergências em tempo real." search={p.search} setSearch={p.setSearch} action={start} actionLabel="Iniciar inventário" />{active ? <div className="library-inventory-workspace"><div className="library-inventory-heading"><div><span className="section-kicker">Conferência em andamento</span><h3>{active.codigo || active.nome || `Inventário #${active.id}`}</h3><p>{read.length} conferidos de {items.length} exemplares · {missing.length} pendentes</p></div><div className="library-form-actions"><button type="button" onClick={requestCancel}>Cancelar</button><button type="button" className="library-primary" disabled={!items.length} onClick={requestFinish}>Concluir inventário</button></div></div><div className="library-inventory-progress"><i style={{ width: `${items.length ? Math.round(read.length / items.length * 100) : 0}%` }} /></div><form className="library-inventory-scan" onSubmit={scan}><label>Código do exemplar<input autoFocus name="codigo" placeholder="Digite ou leia o código de barras" /></label><label>Observação<input name="observacao" placeholder="Opcional: avaria, localização divergente..." /></label><button className="library-primary" type="submit"><Check size={15} /> Registrar leitura</button></form><Table headers={["Exemplar", "Situação", "Leitura", "Observação"]}>{visibleItems.map((item: Row) => <tr key={item.id}><td><strong>{item.codigo_informado || item.exemplar_id}</strong></td><td>{statusLabel(item.situacao_encontrada)}</td><td><span className={`library-pill ${item.lido_em ? "library-pill--green" : "library-pill--orange"}`}>{item.lido_em ? `Conferido às ${time(item.lido_em)}` : "Pendente"}</span></td><td>{item.observacao || "—"}</td></tr>)}</Table><Pagination page={page} total={items.length} onChange={setPage} /></div> : <><Table headers={["Inventário", "Status", "Início", "Progresso", "Ações"]}>{p.inventories.filter((x: Row) => JSON.stringify(x).toLowerCase().includes(p.search.toLowerCase())).map((x: Row) => { const total = p.inventoryItems.filter((item: Row) => item.inventario_id === x.id); const done = total.filter((item: Row) => item.lido_em).length; return <tr key={x.id}><td><strong>{x.codigo || x.nome || `#${x.id}`}</strong><small>{x.observacoes || x.escopo?.descricao || "Conferência do acervo ativo"}</small></td><td><span className={`library-pill ${x.status === "EM_EXECUCAO" ? "library-pill--blue" : x.status === "CONCLUIDO" ? "library-pill--green" : "library-pill--gray"}`}>{statusLabel(x.status)}</span></td><td>{date(x.created_at || x.data_inicio)}</td><td>{done} / {total.length}</td><td>{x.status === "EM_EXECUCAO" && <button type="button" onClick={() => { setSelectedId(x.id); setPage(1); }}>Abrir conferência</button>}</td></tr>; })}</Table><p className="library-muted">Cada inventário mantém o histórico da conferência, dos itens não localizados e das divergências.</p></>}</section>; }
function ConfigPanel(p: any) { const x = p.config; return <section className="library-panel"><Header title="Configurações da Biblioteca" description="Identificação, prazos, limites, renovações, alertas e reservas." search="" setSearch={() => undefined} action={() => p.setForm("configuracoes")} actionLabel="Editar configurações" />{p.form === "configuracoes" && <LibraryModal onClose={() => p.setForm(null)}><form className="library-form" onSubmit={(e: any) => { e.preventDefault(); const d = new FormData(e.currentTarget); void (async () => { if (!p.canManage) return p.setNotice({ kind: "error", text: "Seu perfil não pode alterar as configurações da Biblioteca." }); const r = await supabase.rpc("bib_salvar_configuracao", { p_nome_biblioteca: d.get("nome"), p_prazo_padrao: Number(d.get("padrao")), p_prazo_maximo: Number(d.get("maximo")), p_renovacoes: Number(d.get("renovacoes")), p_limite: Number(d.get("limite")), p_dias_alerta: Number(d.get("alerta")), p_permite_reserva: d.get("reservas") === "on" }); if (r.error) p.setNotice({ kind: "error", text: text(r.error) }); else { p.setForm(null); p.setNotice({ kind: "ok", text: "Configuração salva com sucesso." }); await p.load(); } })(); }}><div className="library-form-grid"><label>Nome da biblioteca<input required name="nome" defaultValue={x.nome_biblioteca || x.nome || "Biblioteca Municipal"} /></label><label>Prazo padrão<input name="padrao" type="number" min="1" defaultValue={x.prazo_padrao_dias || 14} /></label><label>Prazo máximo<input name="maximo" type="number" min="1" defaultValue={x.prazo_maximo_dias || 30} /></label><label>Renovações máximas<input name="renovacoes" type="number" min="0" defaultValue={x.renovacoes_maximas ?? 1} /></label><label>Limite por leitor<input name="limite" type="number" min="1" defaultValue={x.limite_livros_por_leitor || 3} /></label><label>Dias para alerta<input name="alerta" type="number" min="0" defaultValue={x.dias_alerta_atraso ?? 1} /></label><label><input name="reservas" type="checkbox" defaultChecked={x.permite_reserva === true} /> Permitir reservas</label></div><div className="library-form-actions"><button className="library-primary" disabled={p.busy} type="submit"><Check size={15} /> Salvar configuração</button></div></form></LibraryModal>}</section>; }
function ReportsPanel(p: any) { const [period, setPeriod] = useState("30"); const [status, setStatus] = useState("TODOS"); const cutoff = new Date(); cutoff.setDate(cutoff.getDate() - Number(period)); const filtered = p.loans.filter((x: Row) => (!x.data_retirada || new Date(x.data_retirada) >= cutoff) && (status === "TODOS" || x.status === status)); const returned = p.loanItems.filter((x: Row) => x.data_devolucao && new Date(x.data_devolucao) >= cutoff); const delayed = filtered.filter((x: Row) => p.overdue.some((o: Row) => o.id === x.id)); const active = filtered.filter((x: Row) => ["ABERTO", "PARCIAL", "ATRASADO"].includes(x.status)); const bookCounts: Row = {}; returned.forEach((item: Row) => { const copy = p.copies.find((x: Row) => x.id === item.exemplar_id); if (copy) bookCounts[copy.livro_id] = (bookCounts[copy.livro_id] || 0) + 1; }); filtered.forEach((loan: Row) => { p.loanItems.filter((item: Row) => item.emprestimo_id === loan.id).forEach((item: Row) => { const copy = p.copies.find((x: Row) => x.id === item.exemplar_id); if (copy) bookCounts[copy.livro_id] = (bookCounts[copy.livro_id] || 0) + 1; }); }); const topBooks = Object.entries(bookCounts).sort((a, b) => Number(b[1]) - Number(a[1])).slice(0, 5); const exportCsv = () => { const lines = [["codigo", "leitor", "retirada", "prazo", "status"], ...filtered.map((x: Row) => [x.codigo || x.id, p.readerName(x.leitor_id), x.data_retirada, x.prazo_devolucao, x.status])].map((x) => x.map((v: any) => `"${String(v ?? "").replaceAll('"', '""')}"`).join(",")).join("\n"); const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([lines], { type: "text/csv;charset=utf-8" })); a.download = `relatorio-circulacao-${period}-dias.csv`; a.click(); URL.revokeObjectURL(a.href); }; return <section className="library-panel"><Header title="Relatórios operacionais" description="Acompanhe circulação, atrasos, devoluções e livros mais movimentados por período." search={p.search} setSearch={p.setSearch} /><div className="library-report-filters"><label>Período<select value={period} onChange={(e) => setPeriod(e.target.value)}><option value="7">Últimos 7 dias</option><option value="30">Últimos 30 dias</option><option value="90">Últimos 90 dias</option><option value="365">Último ano</option></select></label><label>Status<select value={status} onChange={(e) => setStatus(e.target.value)}><option>TODOS</option><option>ABERTO</option><option>PARCIAL</option><option>ATRASADO</option><option>DEVOLVIDO</option></select></label><button className="library-primary" type="button" onClick={exportCsv}><FileText size={15} /> Exportar CSV</button><button type="button" onClick={() => window.print()}>Imprimir relatório</button></div><div className="library-shortcuts"><Shortcut icon={BarChart3} title="Empréstimos" value={`${filtered.length} no período`} /><Shortcut icon={Check} title="Devoluções" value={`${returned.length} itens`} /><Shortcut icon={CircleAlert} title="Atrasados" value={`${delayed.length} empréstimos`} /><Shortcut icon={Users} title="Em circulação" value={`${active.length} empréstimos`} /></div><div className="library-report-grid"><section className="library-dashboard-card"><div className="library-card-heading"><div><span className="section-kicker">Demanda</span><h3>Livros mais movimentados</h3></div></div>{topBooks.length ? topBooks.map(([id, count]) => <div className="library-activity" key={id}><span className="activity-dot" /><div><strong>{p.bookTitle(Number(id))}</strong><small>{count} movimentação(ões) no período</small></div></div>) : <p className="library-muted">Sem movimentações no período selecionado.</p>}</section><section className="library-dashboard-card"><div className="library-card-heading"><div><span className="section-kicker">Acervo</span><h3>Visão geral</h3></div></div><div className="library-report-summary"><span><strong>{p.books.length}</strong> obras cadastradas</span><span><strong>{p.copies.length}</strong> exemplares físicos</span><span><strong>{p.available.length}</strong> disponíveis agora</span><span><strong>{p.reservations.length}</strong> reservas registradas</span></div></section></div></section>; }
function AuditPanel(p: any) { return <section className="library-panel"><Header title="Histórico e notificações" description="Histórico das operações e avisos da biblioteca." search={p.search} setSearch={p.setSearch} /><h3>Auditoria</h3><Table headers={["Data", "Ação", "Entidade", "Usuário", "Detalhes"]}>{p.audit.filter((x: Row) => JSON.stringify(x).toLowerCase().includes(p.search.toLowerCase())).map((x: Row) => <tr key={x.id}><td>{date(x.created_at)}</td><td>{x.acao || x.operacao || "—"}</td><td>{x.entidade || x.tabela || "—"}</td><td>{x.usuario_id || "—"}</td><td>{x.detalhes ? JSON.stringify(x.detalhes) : "—"}</td></tr>)}</Table><h3>Notificações</h3><Table headers={["Data", "Título", "Mensagem", "Status"]}>{p.notifications.map((x: Row) => <tr key={x.id}><td>{date(x.created_at)}</td><td>{x.titulo || "—"}</td><td>{x.mensagem || x.conteudo || "—"}</td><td>{x.lida ? "Lida" : "Não lida"}</td></tr>)}</Table></section>; }
function Help() { return <section className="library-panel"><span className="section-kicker">Manual operacional</span><h2>Como operar a Biblioteca</h2><div className="library-help-grid"><article><h3>Catálogo e acervo</h3><p>Cadastre obras, autores, editoras e categorias. Depois registre cada exemplar com código, conservação e localização.</p></article><article><h3>Circulação</h3><p>Empréstimos respeitam leitor ativo, limite configurado e prazo máximo. Devoluções podem ser parciais e as renovações seguem as regras da biblioteca.</p></article><article><h3>Governança</h3><p>Reservas, bloqueios, inventário, documentos, notificações e histórico são protegidos e acessíveis apenas a usuários autorizados.</p></article></div></section>; }
function LibraryModal({ children, onClose }: { children: ReactNode; onClose: () => void }) { useEffect(() => { const onKeyDown = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); }; document.addEventListener("keydown", onKeyDown); return () => document.removeEventListener("keydown", onKeyDown); }, [onClose]); return <div className="library-modal-backdrop" role="presentation" onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}><div className="library-modal" role="dialog" aria-modal="true">{children}</div></div>; }
function FeedbackModal({ notice, onClose }: any) { useEffect(() => { const onKeyDown = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); }; document.addEventListener("keydown", onKeyDown); return () => document.removeEventListener("keydown", onKeyDown); }, [onClose]); return <div className="library-modal-backdrop" role="presentation" onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}><div className={`library-modal library-feedback library-feedback--${notice.kind}`} role="dialog" aria-modal="true"><div className="library-feedback-icon">{notice.kind === "ok" ? <Check size={24} /> : <CircleAlert size={24} />}</div><h3>{notice.kind === "ok" ? "Operação concluída" : "Não foi possível concluir"}</h3><p>{notice.text}</p><button className="library-primary" type="button" onClick={onClose}>Entendi</button></div></div>; }
function ConfirmModal({ confirm, busy, onCancel, onConfirm }: any) { return <div className="library-modal-backdrop" role="presentation"><div className="library-modal library-feedback" role="dialog" aria-modal="true"><div className="library-feedback-icon library-feedback-icon--warning"><CircleAlert size={24} /></div><h3>{confirm.title}</h3><p>{confirm.message}</p><div className="library-form-actions"><button type="button" onClick={onCancel}>Cancelar</button><button className="library-primary" type="button" disabled={busy} onClick={onConfirm}>Confirmar</button></div></div></div>; }
function Table({ headers, children }: any) { return <div className="library-table-wrap"><table className="library-table"><thead><tr>{headers.map((x: string) => <th key={x}>{x}</th>)}</tr></thead><tbody>{children}</tbody></table></div>; }
function Empty({ label, action }: any) { return <div className="library-empty"><BookOpen size={30} /><strong>{label}</strong>{action && <button className="library-primary" type="button" onClick={action}><Plus size={15} /> Criar cadastro</button>}</div>; }
